import questionary as q
from typing import List, Dict, Any
import math

from hydraulics.constants import FITTING_PARAMS
from hydraulics.fittings import (
    Fitting,
    FittingType,
    calculate_thrust_force,
    get_fitting_type,
    create_fitting,
)
from soils.soil_enum import *
from soils.soil_mechanics import *

# --- Input Utilities ---

def ask_numeric(prompt: str, positive: bool = True) -> float:
    """Prompt for a numeric value, optionally enforcing positivity."""
    return float(
        q.text(
            prompt,
            validate=lambda val: (
                val.replace('.', '', 1).isdigit() and (float(val) > 0 if positive else True)
            ) or "Please enter a valid number."
        ).ask()
    )

def ask_enum(prompt: str, enum_cls) -> Any:
    """Prompt for a value from an Enum class."""
    choices = [e.value.capitalize() for e in enum_cls]
    selected = q.select(prompt, choices=choices).ask()
    for e in enum_cls:
        if e.value.lower() == selected.lower():
            return e
    raise ValueError(f"Unknown selection: {selected}")

def ask_select(prompt: str, choices: List[str]) -> str:
    """Prompt for a selection from a list of choices."""
    return q.select(prompt, choices=choices).ask()

# --- Hydraulics ---

def get_maximum_design_pressure() -> float:
    return ask_numeric("Enter maximum design pressure (kPa): ")

def get_fitting_type_from_user_input() -> str:
    return ask_select("Select fitting type:", [ft.value for ft in FittingType])

def get_fitting_parameters(fitting_type: str) -> dict:
    params = FITTING_PARAMS[get_fitting_type(fitting_type)]
    param_values = {}
    for param_name, prompt, param_type in params:
        value = ask_numeric(prompt, positive=False)
        param_values[param_name] = param_type(value)
    return param_values

# --- Soils ---

def get_soil_category_from_user_input() -> SoilCategory:
    return ask_enum("Select soil category:", SoilCategory)

def get_soil_type_from_user_input(soil_category: SoilCategory) -> SoilType:
    category_to_types = {
        SoilCategory.COARSE: [SoilType.GRAVEL, SoilType.SAND],
        SoilCategory.FINE: [SoilType.SILT, SoilType.CLAY],
        SoilCategory.VERY_COARSE: [SoilType.BOULDER, SoilType.COBBLE],
        SoilCategory.ROCK: [SoilType.CEMENT],
        # Add ORGANIC, ANTHROPOGENIC if needed
    }
    types = category_to_types.get(soil_category)
    if not types:
        raise ValueError(f"No soil types available for category {soil_category.name}")
    choices = [st.label.capitalize() for st in types]
    soil_type_label = ask_select("Select soil type", choices)
    return get_soil_type(soil_type_label)

def get_soil_consistency_from_user_input(soil_category: SoilCategory) -> Consistency:
    consistencies = [c for c in Consistency if c.category == soil_category]
    choices = [c.label.capitalize() for c in consistencies]
    consistency_label = ask_select("Select soil consistency:", choices)
    return get_soil_consistency(consistency_label)

def get_water_condition_from_user_input() -> WaterCondition:
    return ask_enum("Select water condition:", WaterCondition)

def get_depth_ground_water_level_from_user_input() -> float:
    return ask_numeric("Enter depth of groundwater level from ground level: ")

def get_user_properties(soil_category: SoilCategory) -> dict:
    if soil_category == SoilCategory.COARSE:
        friction_angle = ask_numeric("Enter soil friction angle (degrees):")
        return {"cohesion": 0, "friction_angle": friction_angle, "sliding_resistance": (2.5, 3.0)}
    elif soil_category == SoilCategory.FINE:
        shear_strength = ask_numeric("Enter undrained shear strength (kPa):")
        return {"cohesion": shear_strength, "friction_angle": 0, "sliding_resistance": (1.0, 1.5)}
    else:
        raise ValueError(f"Unexpected soil category: {soil_category}")

def is_soil_properties(
    soil_type: SoilType,
    soil_category: SoilCategory,
    soil_consistency: Consistency
) -> Soil:
    choices = ["Yes", "No"]
    if soil_category == SoilCategory.COARSE:
        is_known = ask_select("Is friction angle of coarse soil known?", choices)
        if is_known == "Yes":
            user_properties = get_user_properties(soil_category)
            return Soil(soil_type=soil_type, consistency=soil_consistency, user_properties=user_properties)
        else:
            return Soil(soil_type=soil_type, consistency=soil_consistency)
    elif soil_category == SoilCategory.FINE:
        is_known = ask_select("Is undrained shear strength of fine soil known?", choices)
        if is_known == "Yes":
            user_properties = get_user_properties(soil_category)
            return Soil(soil_type=soil_type, consistency=soil_consistency, user_properties=user_properties)
        else:
            return Soil(soil_type=soil_type, consistency=soil_consistency)
    else:
        raise ValueError(f"Unexpected soil category: {soil_category}")
    
# --- Thrust Block ---

# --- Main Execution ---

def main():
    maximum_design_pressure = get_maximum_design_pressure()
    fitting = get_fitting_type_from_user_input()
    fitting_params = get_fitting_parameters(fitting)
    print(f"Maximum Design Pressure: {maximum_design_pressure} kPa | "
          f"Fitting Type: {fitting} | "
          f"Fitting Parameters: {fitting_params}")

    fitting_type = get_fitting_type(fitting)
    fitting_instance = create_fitting(fitting_type, **fitting_params)
    print(f"Instantiated Fitting: {fitting_instance}")

    thrust_force = calculate_thrust_force(fitting_instance, maximum_design_pressure)
    print(f"Calculated Thrust Force: {thrust_force} kN")

    soil_category = get_soil_category_from_user_input()
    print(f"Selected Soil Category: {soil_category}")

    soil_type = get_soil_type_from_user_input(soil_category)
    print(f"Selected Soil Type: {soil_type}")

    soil_consistency = get_soil_consistency_from_user_input(soil_category)
    print(f"Selected Soil Consistency: {soil_consistency.label}")

    check_class = classify_soil(soil_type, soil_consistency)
    print(f"Design class: {check_class}")
    print(f"Selected native soil type: {soil_consistency.label} {soil_type.label}")

    water_condition = get_water_condition_from_user_input()
    depth_ground_water = get_depth_ground_water_level_from_user_input()
    print(f"You selected '{water_condition.value}' at a depth of {depth_ground_water}")

    soil_obj = is_soil_properties(soil_type, soil_category, soil_consistency)
    print(f"Soil properties object created: {soil_obj}")
    # buoyancy_coefficient = calculate_buoyancy_coefficient()  # Uncomment if needed

if __name__ == "__main__":
    main()